-- FUTUREUNI Internal Platform: initial schema (docs/specs/data-model.md).
-- Generated by Prisma Migrate, then extended by hand with what the Prisma schema can't express:
-- the extensions (top) and the CHECK constraints (bottom), each naming the invariant it enforces
-- (data-model §6). Partial unique indexes, GIN and trigram indexes are declared natively in the
-- schema (partialIndexes preview feature), so Prisma Migrate tracks them.

-- §6 #1: case-insensitive emails and domains (citext); fuzzy company matching (pg_trgm).
-- Created before any table, because citext columns and the trigram index depend on them.
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

