-- ============================================================================================
-- CHECK constraints (data-model §6). Prisma doesn't model CHECK constraints and leaves them alone.
-- ============================================================================================

-- §6 #15 (ADR-009): country codes are ISO 3166-1 alpha-2, upper case.
ALTER TABLE "companies" ADD CONSTRAINT "companies_country_iso2_check" CHECK ("country" IS NULL OR "country" ~ '^[A-Z]{2}$');
ALTER TABLE "acq_leads" ADD CONSTRAINT "acq_leads_country_iso2_check" CHECK ("country" IS NULL OR "country" ~ '^[A-Z]{2}$');

-- §6 #4 (scoring spec): a lead score is 0-100.
ALTER TABLE "acq_leads" ADD CONSTRAINT "acq_leads_score_range" CHECK ("score" IS NULL OR "score" BETWEEN 0 AND 100);

-- §6 #5 (INV-11): money is never negative; a line item has a positive quantity.
ALTER TABLE "acq_proposals" ADD CONSTRAINT "acq_proposals_money_nonnegative_check" CHECK (
  "subtotalMinor" >= 0 AND "discountMinor" >= 0 AND "taxMinor" >= 0 AND "totalMinor" >= 0
  AND "discountValue" >= 0 AND "taxRateBps" >= 0
);
ALTER TABLE "acq_proposal_line_items" ADD CONSTRAINT "acq_proposal_line_items_money_check" CHECK (
  "unitPriceMinor" >= 0 AND "totalMinor" >= 0 AND "quantity" > 0
);
ALTER TABLE "acq_deals" ADD CONSTRAINT "acq_deals_value_nonnegative_check" CHECK ("valueMinor" IS NULL OR "valueMinor" >= 0);

-- §6 #6 (ADR-027): internal costs (micro-USD) are never negative.
ALTER TABLE "ai_calls" ADD CONSTRAINT "ai_calls_cost_nonnegative_check" CHECK ("costMicros" >= 0);
ALTER TABLE "provider_usages" ADD CONSTRAINT "provider_usages_cost_nonnegative_check" CHECK ("costMicros" >= 0);
ALTER TABLE "acq_search_runs" ADD CONSTRAINT "acq_search_runs_cost_nonnegative_check" CHECK ("costMicros" >= 0 AND ("estimatedCostMicros" IS NULL OR "estimatedCostMicros" >= 0));
ALTER TABLE "acq_audits" ADD CONSTRAINT "acq_audits_cost_nonnegative_check" CHECK ("costMicros" >= 0);
ALTER TABLE "acq_audit_check_runs" ADD CONSTRAINT "acq_audit_check_runs_cost_nonnegative_check" CHECK ("costMicros" >= 0);

-- §6 #7 (INV-8): mailbox caps and the warm-up ramp are positive.
ALTER TABLE "acq_mailboxes" ADD CONSTRAINT "acq_mailboxes_caps_positive_check" CHECK (
  "dailyCapTarget" > 0 AND "warmupStartCap" > 0 AND "warmupRampDays" > 0
);

-- §6 #8 (INV-5): a citation points at exactly one finding or signal.
ALTER TABLE "acq_message_citations" ADD CONSTRAINT "acq_message_citations_one_source_check" CHECK (num_nonnulls("findingId", "signalId") = 1);

-- §6 #9 (INV-18): a finding has a source URL or an artifact, and a confidence of 0-1.
ALTER TABLE "acq_audit_findings" ADD CONSTRAINT "acq_audit_findings_source_check" CHECK ("sourceUrl" IS NOT NULL OR "artifactKey" IS NOT NULL);
ALTER TABLE "acq_audit_findings" ADD CONSTRAINT "acq_audit_findings_confidence_check" CHECK ("confidence" BETWEEN 0 AND 1);

-- §6 #12 (INV-2): a removed suppression records why (the row stays for history).
ALTER TABLE "acq_suppressions" ADD CONSTRAINT "acq_suppressions_removed_reason_check" CHECK ("removedAt" IS NULL OR "removedReason" IS NOT NULL);

-- §6 #17 (settings contract): USER-scope settings belong to a user; other scopes never do. With the
-- two partial unique indexes, this gives one row per (key, scope) or (key, scope, userId).
ALTER TABLE "settings" ADD CONSTRAINT "settings_user_scope_check" CHECK (("scope" = 'USER') = ("userId" IS NOT NULL));

-- §6 #20 (won/lost spec): a won deal has a value and currency; a lost deal has a reason.
ALTER TABLE "acq_deals" ADD CONSTRAINT "acq_deals_won_value_check" CHECK ("outcome" <> 'WON' OR ("valueMinor" IS NOT NULL AND "currency" IS NOT NULL));
ALTER TABLE "acq_deals" ADD CONSTRAINT "acq_deals_lost_reason_check" CHECK ("outcome" <> 'LOST' OR "lostReason" IS NOT NULL);

-- §6 #21 (INV-3 traceability): a stopped enrolment records why.
ALTER TABLE "acq_enrollments" ADD CONSTRAINT "acq_enrollments_stop_reason_check" CHECK ("status" <> 'STOPPED' OR "stoppedReason" IS NOT NULL);

-- §6 #22 (INV-1): a status-change event records the new status.
ALTER TABLE "acq_lead_events" ADD CONSTRAINT "acq_lead_events_status_change_check" CHECK ("kind" <> 'STATUS_CHANGE' OR "toStatus" IS NOT NULL);

-- §6 #23 (scoring spec): a human decision is QUALIFY or DISQUALIFY; an override has a note.
ALTER TABLE "acq_score_reviews" ADD CONSTRAINT "acq_score_reviews_decision_check" CHECK ("humanDecision" IS NULL OR "humanDecision" IN ('QUALIFY', 'DISQUALIFY'));
ALTER TABLE "acq_score_reviews" ADD CONSTRAINT "acq_score_reviews_override_note_check" CHECK ("decisionType" IS NULL OR "decisionType" <> 'OVERRIDDEN' OR "overrideNote" IS NOT NULL);

-- §6 #26 (calendar webhooks): a meeting ends after it starts.
ALTER TABLE "acq_meetings" ADD CONSTRAINT "acq_meetings_time_order_check" CHECK ("endsAt" > "startsAt");

-- §6 #27 (INV-6, INV-10): consent records and data-subject requests identify someone.
ALTER TABLE "acq_consent_records" ADD CONSTRAINT "acq_consent_records_subject_check" CHECK ("contactId" IS NOT NULL OR "email" IS NOT NULL);
ALTER TABLE "acq_data_subject_requests" ADD CONSTRAINT "acq_data_subject_requests_subject_check" CHECK ("subjectEmail" IS NOT NULL OR "subjectPhone" IS NOT NULL);

-- §6 #28 (data integrity): counters are never negative; a stored file has content.
ALTER TABLE "team_profiles" ADD CONSTRAINT "team_profiles_counters_check" CHECK ("weeklyCapacity" >= 0 AND "currentLoad" >= 0);
ALTER TABLE "acq_mailbox_daily_stats" ADD CONSTRAINT "acq_mailbox_daily_stats_counters_check" CHECK (
  "sent" >= 0 AND "bouncesHard" >= 0 AND "bouncesSoft" >= 0 AND "complaints" >= 0 AND "replies" >= 0
);
ALTER TABLE "acq_inbox_threads" ADD CONSTRAINT "acq_inbox_threads_unread_check" CHECK ("unreadCount" >= 0);
ALTER TABLE "provider_usages" ADD CONSTRAINT "provider_usages_calls_check" CHECK ("calls" >= 0);
ALTER TABLE "acq_sequence_steps" ADD CONSTRAINT "acq_sequence_steps_delay_check" CHECK ("delayBusinessDays" >= 0);
ALTER TABLE "file_objects" ADD CONSTRAINT "file_objects_size_check" CHECK ("sizeBytes" > 0);

-- §6 #29 (INV-5): a signal has a source URL unless it was entered by hand or imported.
ALTER TABLE "acq_signals" ADD CONSTRAINT "acq_signals_source_check" CHECK ("sourceUrl" IS NOT NULL OR "adapterId" IN ('manual', 'csv-import'));
